import json,sys,hashlib,zlib,base64
data=json.loads(zlib.decompress(base64.b64decode('')))
namespace={'__name__':'readonly_environment'}
exec(compile(data['environment'],'crowdbastion_environment.py','exec'),namespace)
failures={}
for name,source in data['sources'].items():
 try:compile(source,name,'exec')
 except Exception as error:failures[name]=type(error).__name__+': '+str(error)
print(json.dumps({'python':sys.version,'environment':namespace['check_environment'](interval=1,samples=5),'source_compile':{'count':len(data['sources']),'failures':failures},'environment_source_sha256':hashlib.sha256(data['environment'].encode()).hexdigest()},ensure_ascii=True,indent=2))
